import{_ as e}from"./chunks/sh2.C2f6EkLz.js";import{_ as t,c as o,o as l,ae as i}from"./chunks/framework.BrQRMotl.js";const _=JSON.parse('{"title":"高级模式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/advanced_mode.md","filePath":"zh/manual/advanced_mode.md"}'),n={name:"zh/manual/advanced_mode.md"};function s(r,a,d,c,h,m){return l(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="高级模式" tabindex="-1">高级模式 <a class="header-anchor" href="#高级模式" aria-label="Permalink to &quot;高级模式&quot;">​</a></h1><p>在扩展音符盒界面，你可以找到 <strong>“高级模式”</strong> 入口。进入后，你将解锁更强大的音频渲染控制。</p><p><img src="'+e+'" alt="Advanced Mode"></p><h2 id="可视化包络线" tabindex="-1">可视化包络线 <a class="header-anchor" href="#可视化包络线" aria-label="Permalink to &quot;可视化包络线&quot;">​</a></h2><p>高级模式提供了两个核心的可视化编辑器：</p><h3 id="_1-音量包络" tabindex="-1">1. 音量包络 <a class="header-anchor" href="#_1-音量包络" aria-label="Permalink to &quot;1. 音量包络&quot;">​</a></h3><ul><li>控制声音在播放过程中的音量变化。</li><li><strong>编辑</strong>: 点击并拖动曲线上的点来改变形状。</li><li><strong>作用</strong>: 实现复杂的淡入淡出、颤音或逐渐减弱的效果。</li><li><strong>注意</strong>: 当普通模式下的淡入淡出和高级模式下的音量包络同时存在时，高级模式下的音量包络将覆盖普通模式的淡入淡出。</li></ul><h3 id="_2-音高包络" tabindex="-1">2. 音高包络 <a class="header-anchor" href="#_2-音高包络" aria-label="Permalink to &quot;2. 音高包络&quot;">​</a></h3><ul><li>控制播放过程中的音高偏移。</li><li><strong>编辑</strong>: 同上。</li><li><strong>作用</strong>: 实现滑音、音高抖动或特殊的音效处理。</li><li><strong>注意</strong>: 当普通模式下的音高和高级模式下的音高包络同时存在时，高级模式下的音高包络将覆盖普通模式的音高。</li></ul><hr><h2 id="动态声源移动" tabindex="-1">动态声源移动 <a class="header-anchor" href="#动态声源移动" aria-label="Permalink to &quot;动态声源移动&quot;">​</a></h2><p>这是 Extended Note Block 的特色功能，允许声音在空间中随时间“游走”。通过输入 <strong>数学表达式</strong>，你可以定义声源在 X、Y、Z 轴上的相对偏移。</p><h3 id="变量说明" tabindex="-1">变量说明： <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明：&quot;">​</a></h3><ul><li><code>t</code>: 当前播放进度的百分比 (0.0 到 1.0)。</li><li><code>d</code>: 当前播放的时间，单位为 Tick (1 Tick = 0.05 秒)。</li><li><code>pi</code>: 常数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>π</mi></mrow><annotation encoding="application/x-tex">\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03588em;">π</span></span></span></span> (约 3.14159)。</li></ul><h3 id="常用函数" tabindex="-1">常用函数： <a class="header-anchor" href="#常用函数" aria-label="Permalink to &quot;常用函数：&quot;">​</a></h3><p>支持 <code>sin</code>, <code>cos</code>, <code>tan</code>, <code>abs</code>, <code>sqrt</code>, <code>log</code>, <code>exp</code> 等标准数学函数。</p><h3 id="示例用法" tabindex="-1">示例用法： <a class="header-anchor" href="#示例用法" aria-label="Permalink to &quot;示例用法：&quot;">​</a></h3><ul><li><strong>圆周运动</strong>: <ul><li>X 轴: <code>5 * sin(2 * pi * t)</code></li><li>Z 轴: <code>5 * cos(2 * pi * t)</code></li><li><em>效果: 声源会以 5 格为半径绕着音符盒旋转一圈。</em></li></ul></li><li><strong>垂直上升</strong>: <ul><li>Y 轴: <code>t * 10</code></li><li><em>效果: 声音会随着播放逐渐升高 10 格。</em></li></ul></li><li><strong>正弦上下摆动</strong>: <ul><li>Y 轴: <code>sin(d * 0.5)</code></li><li><em>效果: 声音会上下摆动。</em></li></ul></li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>表达式输入框若出现红色提示，说明语法有误。</li></ul>',20)])])}const g=t(n,[["render",s]]);export{_ as __pageData,g as default};
